194	    /**
195	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
196	     */
197	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
198	
199	    /**
200	     * Required national-number length per country calling code. When the normalized E.164 number
201	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
202	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
203	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
204	     */
205	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
206	        "+61", 9,
207	        "+1", 10);
208	
209	    /**
210	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
211	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
212	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
213	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
214	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
215	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
216	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
217	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
218	     * translates to a 400.
219	     */
220	    private static String normalizeTelephone(String telephone) {
221	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
222	        String e164;
223	        if (cleaned.startsWith("+")) {
224	            e164 = cleaned;
225	        } else {
226	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
227	            e164 = "+61" + national;
228	        }
229	        if (!E164_PATTERN.matcher(e164).matches()) {
230	            throw new InvalidTelephoneException(telephone);
231	        }
232	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
233	            String code = rule.getKey();
234	            if (e164.startsWith(code)) {
235	                int nationalLength = e164.length() - code.length();
236	                if (nationalLength != rule.getValue()) {
237	                    throw new InvalidTelephoneException(telephone);
238	                }
239	                break;
240	            }
241	        }
242	        return e164;
243	    }
244	
245	    /**
246	     * Matches a well-formed postcode: exactly four digits.
247	     */
248	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
249	
250	    /**
251	     * The canonical region for each city that has one. A city absent from this table has no known
252	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
253	     * to derive an owner's locality.
254	     */
255	    private static final Map<String, String> CITY_REGION = Map.of(
256	        "Sydney", "NSW",
257	        "Melbourne", "VIC",
258	        "Brisbane", "QLD");
259	
260	    /**
261	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
262	     * VIC 3000-3099, QLD 4000-4099.
263	     */
264	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
265	        "NSW", new int[] {2000, 2099},
266	        "VIC", new int[] {3000, 3099},
267	        "QLD", new int[] {4000, 4099});
268	
269	    /**
270	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
271	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
272	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
273	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
274	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
275	     * exception handler translates to a 400.
276	     */
277	    private static void validatePostcode(String city, String postcode) {
278	        if (postcode == null) {
279	            return;
280	        }
281	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
282	            throw new InvalidPostcodeException(postcode);
283	        }
284	        String region = CITY_REGION.get(city);
285	        if (region == null) {
286	            return;
287	        }
288	        int[] range = REGION_POSTCODES.get(region);
289	        int value = Integer.parseInt(postcode);
290	        if (value < range[0] || value > range[1]) {
291	            throw new InvalidPostcodeException(postcode);
292	        }
293	    }
