295	    /**
296	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
297	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
298	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
299	     */
300	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
301	
302	    /**
303	     * Disposable-email domains that an owner's email may not use. An address whose domain (the part
304	     * after the final {@code @}, compared case-insensitively) is one of these is rejected. Kept as a
305	     * fixed set so the block list is explicit and easy to extend.
306	     */
307	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
308	        "mailinator.com",
309	        "tempmail.com",
310	        "guerrillamail.com");
311	
312	    /**
313	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
314	     * optional). When present it must be a syntactically valid address whose domain is not on the
315	     * disposable-domain block list; a valid value is lower-cased so it is stored and returned in
316	     * canonical form. An invalid or disposable-domain value is rejected via
317	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
318	     */
319	    private static String normalizeEmail(String email) {
320	        if (email == null) {
321	            return null;
322	        }
323	        if (!EMAIL_PATTERN.matcher(email).matches()) {
324	            throw new InvalidEmailException(email);
325	        }
326	        String normalized = email.toLowerCase(Locale.ROOT);
327	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
328	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
329	            throw new InvalidEmailException(email);
330	        }
331	        return normalized;
332	    }
