334	    /**
335	     * The single derived identity of an owner: the 64-character lower-case SHA-256 hex digest over
336	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, into which all
337	     * duplicate detection is consolidated. Two owners are the same identity only when this whole key
338	     * matches: because the normalized telephone is part of the pre-image, two owners who share a
339	     * surname (same soundex) and postcode but carry different telephones have different identity
340	     * keys. A {@code null} email contributes an empty middle segment. This is the value returned to
341	     * callers as {@code identityKey}.
342	     */
343	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String lastName) {
344	        String preimage = normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail)
345	            + "|" + soundex(lastName);
346	        return sha256Hex(preimage);
347	    }
348	
349	    /**
350	     * The American Soundex code of a name: its first letter followed by up to three digits encoding
351	     * the remaining consonants (b/f/p/v->1, c/g/j/k/q/s/x/z->2, d/t->3, l->4, m/n->5, r->6), with
352	     * adjacent duplicate codes collapsed, vowels (and y) resetting the run, and h/w transparent so
353	     * consonants they separate are still treated as adjacent. The result is padded with zeros to
354	     * exactly four characters. A {@code null} or letterless name yields the empty string.
355	     */
356	    private static String soundex(String name) {
357	        if (name == null) {
358	            return "";
359	        }
360	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
361	        if (letters.isEmpty()) {
362	            return "";
363	        }
364	        StringBuilder code = new StringBuilder();
365	        code.append(letters.charAt(0));
366	        char prev = soundexCode(letters.charAt(0));
367	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
368	            char c = letters.charAt(i);
369	            if (c == 'H' || c == 'W') {
370	                continue;
371	            }
372	            char digit = soundexCode(c);
373	            if (digit != '0' && digit != prev) {
374	                code.append(digit);
375	            }
376	            prev = digit;
377	        }
378	        while (code.length() < 4) {
379	            code.append('0');
380	        }
381	        return code.toString();
382	    }
383	
384	    /**
385	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a vowel, y, h or w (which
386	     * carry no code).
387	     */
388	    private static char soundexCode(char c) {
389	        return switch (c) {
390	            case 'B', 'F', 'P', 'V' -> '1';
391	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
392	            case 'D', 'T' -> '3';
393	            case 'L' -> '4';
394	            case 'M', 'N' -> '5';
395	            case 'R' -> '6';
396	            default -> '0';
397	        };
398	    }
399	
400	    /**
401	     * The full lower-case SHA-256 hex digest (64 characters) of the UTF-8 bytes of {@code value}.
402	     */
403	    private static String sha256Hex(String value) {
404	        try {
405	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
406	            StringBuilder sb = new StringBuilder(digest.length * 2);
407	            for (byte b : digest) {
408	                sb.append(String.format("%02x", b));
409	            }
410	            return sb.toString();
411	        } catch (NoSuchAlgorithmException ex) {
412	            throw new IllegalStateException("SHA-256 not available", ex);
413	        }
414	    }
415	
416	    /**
417	     * Rejects a create whose derived identity collides with an existing owner's, reported via
418	     * {@link DuplicateTelephoneException} which the handler translates to a 409. Duplicate detection
419	     * is now the single identity key: the new owner's {@link #identityKeyFor identityKey} (the
420	     * SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}) is
421	     * compared against each existing owner's, ignoring owners flagged deleted. The email-domain
422	     * block list has already been applied while normalizing the email, so it takes effect first. An
423	     * existing telephone that cannot form a valid E.164 number is skipped rather than colliding.
424	     * Because the telephone is part of the key, two owners with the same surname and postcode but
425	     * different telephones no longer collide here - they are surfaced as a soft match instead. The
426	     * former separate telephone, email and household 409 blocks are all subsumed by this key.
427	     */
428	    private void rejectDuplicateIdentity(String normalizedTelephone, String normalizedEmail, String lastName) {
429	        String identityKey = identityKeyFor(normalizedTelephone, normalizedEmail, lastName);
430	        for (Owner existing : this.clinicService.findAllOwners()) {
431	            if (existing.isDeleted()) {
432	                continue;
433	            }
434	            String existingTelephone;
435	            try {
436	                existingTelephone = normalizeTelephone(existing.getTelephone());
437	            } catch (InvalidTelephoneException ex) {
438	                continue;
439	            }
440	            String existingEmail = existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT);
441	            String existingKey = identityKeyFor(existingTelephone, existingEmail, existing.getLastName());
442	            if (identityKey.equals(existingKey)) {
443	                throw new DuplicateTelephoneException(normalizedTelephone);
444	            }
445	        }
446	    }
