448	    /**
449	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
450	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
451	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
452	     * spacing do not defeat the duplicate-household check.
453	     */
454	    private static String collapse(String value) {
455	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
456	    }
457	
458	    /**
459	     * Normalizes an owner's address into a canonical form applied on every create: leading and
460	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
461	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
462	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
463	     * and returned, and is the form every address comparison (duplicate-household detection and the
464	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
465	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
466	     * so normalizing an already-normalized address is a no-op.
467	     */
468	    private static String normalizeAddress(String address) {
469	        if (address == null) {
470	            return "";
471	        }
472	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
473	        if (collapsed.isEmpty()) {
474	            return "";
475	        }
476	        String[] tokens = collapsed.split(" ");
477	        StringBuilder sb = new StringBuilder(collapsed.length());
478	        for (int i = 0; i < tokens.length; i++) {
479	            String token = tokens[i];
480	            switch (token) {
481	                case "ST" -> token = "STREET";
482	                case "RD" -> token = "ROAD";
483	                case "AVE" -> token = "AVENUE";
484	                default -> {
485	                }
486	            }
487	            if (i > 0) {
488	                sb.append(' ');
489	            }
490	            sb.append(token);
491	        }
492	        return sb.toString();
493	    }
494	
495	    /**
496	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
497	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
498	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
499	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
500	     * region derivation shared by the {@code customerCode} and the owner's locality.
501	     */
502	    private static String deriveRegion(String city, String postcode) {
503	        if (postcode != null) {
504	            try {
505	                int pc = Integer.parseInt(postcode.trim());
506	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
507	                    int[] bounds = range.getValue();
508	                    if (pc >= bounds[0] && pc <= bounds[1]) {
509	                        return range.getKey();
510	                    }
511	                }
512	            } catch (NumberFormatException ignored) {
513	                // not a numeric postcode; fall back to the city-to-region table
514	            }
515	        }
516	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
517	    }
518	
519	    /**
520	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
521	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
522	     * city) and {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
523	     * {@code normalizedTelephone + lastName} (e.g. {@code 'NSW-1A2B3C4D'}). This is a stable identity:
524	     * it carries no sequence number and depends only on the owner's own region, telephone and surname.
525	     */
526	    private static String customerCodeFor(String region, String normalizedTelephone, String lastName) {
527	        return region + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
528	    }
529	
530	    /**
531	     * De-duplicates a freshly computed {@code customerCode} against the codes already carried by
532	     * existing owners. When the base code is unused it is returned unchanged; otherwise
533	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
534	     * existing owner already holds. The count reflects the state prior to this create.
535	     */
536	    private String deduplicateCustomerCode(String baseCode) {
537	        Set<String> existingCodes = new HashSet<>();
538	        for (Owner existing : this.clinicService.findAllOwners()) {
539	            String code = existing.getCustomerCode();
540	            if (code != null) {
541	                existingCodes.add(code);
542	            }
543	        }
544	        if (!existingCodes.contains(baseCode)) {
545	            return baseCode;
546	        }
547	        int n = 2;
548	        while (existingCodes.contains(baseCode + "-" + n)) {
549	            n++;
550	        }
551	        return baseCode + "-" + n;
552	    }
553	
554	    /**
555	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
556	     * bytes of {@code value}.
557	     */
558	    private static String sha256HexPrefix(String value, int hexChars) {
559	        try {
560	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
561	            StringBuilder sb = new StringBuilder(hexChars);
562	            for (byte b : digest) {
563	                if (sb.length() >= hexChars) {
564	                    break;
565	                }
566	                sb.append(String.format("%02X", b));
567	            }
568	            return sb.substring(0, hexChars);
569	        } catch (NoSuchAlgorithmException ex) {
570	            throw new IllegalStateException("SHA-256 not available", ex);
571	        }
572	    }
573	
574	    /**
575	     * Builds the {@code membershipNumber} for a newly created owner, formatted
576	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
577	     * fiscal year of the {@code registrationDate} (e.g. {@code 'SMI-0007-M27'}). The year
578	     * segment therefore matches the owner's {@code fiscalYear}.
579	     */
580	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
581	        return String.format("%s-M%02d", customerCode, fiscalYearOf(registrationDate) % 100);
582	    }
583	
584	    /**
585	     * The fiscal year, as a four-digit year, of a business-day-adjusted date. The fiscal year
586	     * starts on 1 July and is labelled by the calendar year in which it ends: a date on or after
587	     * 1 July belongs to the fiscal year ending the following calendar year, while an earlier date
588	     * belongs to the fiscal year ending in its own year.
589	     */
590	    private static int fiscalYearOf(LocalDate date) {
591	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
592	    }
593	
594	    /**
595	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
596	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
597	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
598	     * it is a pure function of that pair, every owner in the same household - whether created first
599	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
600	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
601	     * segment.
602	     */
603	    private static String householdIdFor(String lastName, String postcode) {
604	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
605	        try {
606	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
607	            StringBuilder sb = new StringBuilder(12);
608	            for (byte b : digest) {
609	                if (sb.length() >= 12) {
610	                    break;
611	                }
612	                sb.append(String.format("%02x", b));
613	            }
614	            return sb.substring(0, 12);
615	        } catch (NoSuchAlgorithmException ex) {
616	            throw new IllegalStateException("SHA-256 not available", ex);
617	        }
618	    }
