620	    /**
621	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
622	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
623	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
624	     */
625	    private int countNamesakes(String firstName, String lastName) {
626	        int count = 0;
627	        for (Owner existing : this.clinicService.findAllOwners()) {
628	            if (firstName.equalsIgnoreCase(existing.getFirstName())
629	                && lastName.equalsIgnoreCase(existing.getLastName())) {
630	                count++;
631	            }
632	        }
633	        return count;
634	    }
