636	    /**
637	     * Counts the members of the household the new owner will belong to, as it stands after this
638	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
639	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
640	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
641	     * stored on the owner as its {@code householdMemberCount}.
642	     */
643	    private int countHouseholdMembers(String householdId) {
644	        int count = 1;
645	        for (Owner existing : this.clinicService.findAllOwners()) {
646	            if (householdId.equals(existing.getHouseholdId())) {
647	                count++;
648	            }
649	        }
650	        return count;
651	    }
