653	    /**
654	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
655	     * that is not a hard identity collision but whose {@code lastName} has the same
656	     * {@link #soundex soundex} code as the new owner's and whose {@code postcode} matches, while its
657	     * {@link #identityKeyFor identityKey} differs. The new owner's postcode must be present for a
658	     * soft match to be possible. When several existing owners qualify the one with the lowest id is
659	     * chosen. Returns the matching owner's id, or {@code null} when there is no soft match. This is
660	     * evaluated after the hard-duplicate check has already passed, so any surviving owner sharing the
661	     * surname's soundex and postcode necessarily has a different identity key (typically a different
662	     * telephone). A caller that declares {@code sharesHousehold} is deliberately joining an existing
663	     * household, so it is not flagged as a suspected duplicate.
664	     */
665	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
666	                                            String normalizedEmail) {
667	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
668	            return null;
669	        }
670	        String postcode = ownerFieldsDto.getPostcode();
671	        if (postcode == null) {
672	            return null;
673	        }
674	        String lastName = ownerFieldsDto.getLastName();
675	        if (lastName == null) {
676	            return null;
677	        }
678	        String identityKey = identityKeyFor(normalizedTelephone, normalizedEmail, lastName);
679	        String soundex = soundex(lastName);
680	        Integer matchId = null;
681	        for (Owner existing : this.clinicService.findAllOwners()) {
682	            if (existing.isDeleted()) {
683	                continue;
684	            }
685	            if (!soundex.equals(soundex(existing.getLastName()))) {
686	                continue;
687	            }
688	            if (!postcode.equals(existing.getPostcode())) {
689	                continue;
690	            }
691	            String existingTelephone;
692	            try {
693	                existingTelephone = normalizeTelephone(existing.getTelephone());
694	            } catch (InvalidTelephoneException ex) {
695	                continue;
696	            }
697	            String existingEmail = existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT);
698	            String existingKey = identityKeyFor(existingTelephone, existingEmail, existing.getLastName());
699	            if (identityKey.equals(existingKey)) {
700	                continue;
701	            }
702	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
703	                matchId = existing.getId();
704	            }
705	        }
706	        return matchId;
707	    }
708	
709	    /**
710	     * The tenure, in elapsed fiscal years, that an owner must exceed before its tenure contributes
711	     * membership points. Tenure is measured from the owner's {@code registrationDate}, so a newly
712	     * created owner (whose tenure is zero) never satisfies this and thus never earns the tenure
713	     * points on create.
714	     */
715	    private static final int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
716	
717	    /**
718	     * The household size (number of members) at or above which an owner earns the household points.
719	     */
720	    private static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
721	
722	    /**
723	     * Computes the {@code membershipPoints} for an owner. Points start at 0, gain 2 when an email is
724	     * present, gain 1 when the owner's {@code namesakeCount} is 0, gain 2 when the owner's household
725	     * has {@value #HOUSEHOLD_POINTS_THRESHOLD} or more members, and gain 3 when the owner's tenure
726	     * (elapsed fiscal years since its {@code registrationDate}) exceeds
727	     * {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS}. Because a newly created owner has zero tenure,
728	     * the tenure points never apply on create.
729	     * Evaluated after the owner's email, namesakeCount, householdMemberCount and registrationDate
730	     * have been set.
731	     */
732	    private static int membershipPointsFor(Owner owner) {
733	        int points = 0;
734	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
735	            points += 2;
736	        }
737	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
738	            points += 1;
739	        }
740	        if (owner.getHouseholdMemberCount() != null
741	            && owner.getHouseholdMemberCount() >= HOUSEHOLD_POINTS_THRESHOLD) {
742	            points += 2;
743	        }
744	        if (tenureInFiscalYears(owner) > TENURE_POINTS_THRESHOLD_FISCAL_YEARS) {
745	            points += 3;
746	        }
747	        return points;
748	    }
749	
750	    /**
751	     * Maps {@code membershipPoints} to the numeric {@code membershipLevel}: level 1 for 0-1 points,
752	     * 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
753	     */
754	    private static int membershipLevelForPoints(int points) {
755	        if (points <= 1) {
756	            return 1;
757	        }
758	        if (points <= 3) {
759	            return 2;
760	        }
761	        if (points <= 5) {
762	            return 3;
763	        }
764	        return 4;
765	    }
766	
767	    /**
768	     * Caps a newly computed {@code membershipLevel} so it never exceeds one above the current maximum
769	     * {@code membershipLevel} among the new owner's household members - the existing, non-deleted
770	     * owners already carrying the same {@code householdId}. When the household has no existing member
771	     * (or none with a recorded level) no cap applies and the level is returned unchanged; otherwise the
772	     * level is limited to {@code max(member level) + 1}. The count reflects the state prior to this
773	     * create, as the new owner has not yet been saved.
774	     */
775	    private int capMembershipLevelByHousehold(int membershipLevel, String householdId) {
776	        Integer maxMemberLevel = null;
777	        for (Owner existing : this.clinicService.findAllOwners()) {
778	            if (existing.isDeleted()) {
779	                continue;
780	            }
781	            if (!householdId.equals(existing.getHouseholdId())) {
782	                continue;
783	            }
784	            Integer existingLevel = existing.getMembershipLevel();
785	            if (existingLevel == null) {
786	                continue;
787	            }
788	            if (maxMemberLevel == null || existingLevel > maxMemberLevel) {
789	                maxMemberLevel = existingLevel;
790	            }
791	        }
792	        if (maxMemberLevel == null) {
793	            return membershipLevel;
794	        }
795	        return Math.min(membershipLevel, maxMemberLevel + 1);
796	    }
797	
798	    /**
799	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July fiscal-year boundaries
800	     * crossed between its {@code registrationDate} and the current server date. An owner with no
801	     * registration date, or one dated in the future, has a tenure of zero.
802	     */
803	    private static long tenureInFiscalYears(Owner owner) {
804	        LocalDate registrationDate = owner.getRegistrationDate();
805	        if (registrationDate == null) {
806	            return 0;
807	        }
808	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate));
809	    }
810	
811	    /**
812	     * The maximum number of owners any single city may contain. A create whose city already
813	     * holds this many owners is rejected.
814	     */
815	    private static final int CITY_CAPACITY = 50;
816	
817	    /**
818	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
819	     * compared case-insensitively - the same way the city is matched when building the
820	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
821	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
822	     * translates to a 409.
823	     */
824	    private void rejectCityAtCapacity(String city) {
825	        int count = 0;
826	        for (Owner existing : this.clinicService.findAllOwners()) {
827	            if (city.equalsIgnoreCase(existing.getCity())) {
828	                count++;
829	            }
830	        }
831	        if (count >= CITY_CAPACITY) {
832	            throw new CityAtCapacityException(city);
833	        }
834	    }
835	
836	    /**
837	     * The number of owners a city must already hold before a create in it is flagged with a
838	     * capacity warning. Once a city holds at least this many owners - but is still below the
839	     * {@value #CITY_CAPACITY} hard limit - it is approaching capacity and the new owner's
840	     * {@code capacityWarning} is true.
841	     */
842	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
843	
844	    /**
845	     * Computes the {@code capacityWarning} for a create in the given city: true when the city
846	     * already holds between {@value #CITY_CAPACITY_WARNING_THRESHOLD} and
847	     * {@value #CITY_CAPACITY} (exclusive) owners - approaching the hard capacity limit - otherwise
848	     * false. The city is matched case-insensitively and the count reflects the state prior to this
849	     * create, exactly as {@link #rejectCityAtCapacity(String)} accumulates it.
850	     */
851	    private boolean capacityWarningFor(String city) {
852	        int count = 0;
853	        for (Owner existing : this.clinicService.findAllOwners()) {
854	            if (city.equalsIgnoreCase(existing.getCity())) {
855	                count++;
856	            }
857	        }
858	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
859	    }
860	
861	    /**
862	     * The maximum number of owners that may be created on any single day (by
863	     * {@code registrationDate}). A create attempted once this many owners already carry the
864	     * current day's registration date is rejected.
865	     */
866	    private static final int DAILY_OWNER_LIMIT = 100;
867	
868	    /**
869	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
870	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
871	     * The count reflects the state prior to this create. When the limit is reached the create is
872	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
873	     * to a 429 Too Many Requests.
874	     */
875	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
876	        int count = 0;
877	        for (Owner existing : this.clinicService.findAllOwners()) {
878	            if (registrationDate.equals(existing.getRegistrationDate())) {
879	                count++;
880	            }
881	        }
882	        if (count >= DAILY_OWNER_LIMIT) {
883	            throw new DailyOwnerLimitExceededException();
884	        }
885	    }
886	
887	    /**
888	     * The number of owners that must already carry a given {@code registrationDate} before a
889	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
890	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
891	     */
892	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
893	
894	    /**
895	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
896	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
897	     * have already been created for that date, otherwise false. The count reflects the state prior
898	     * to this create, matching how the daily-limit rule accumulates.
899	     */
900	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
901	        int count = 0;
902	        for (Owner existing : this.clinicService.findAllOwners()) {
903	            if (registrationDate.equals(existing.getRegistrationDate())) {
904	                count++;
905	            }
906	        }
907	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
908	    }
909	
910	    /**
911	     * Rolls an effective registration date forward onto a business day. A Saturday, Sunday or listed
912	     * public holiday is advanced to the next non-holiday business day; a plain weekday is returned
913	     * unchanged. This is applied to the effective registration date - whether supplied in the request
914	     * or defaulted to the server date - so the stored {@code registrationDate}, and everything derived
915	     * from it, always falls on a business day.
916	     */
917	    /**
918	     * Rejects a supplied {@code registrationDate} that lies in the future. A registration date is
919	     * only ever explicitly supplied on the request; when present it must not be later than the
920	     * current server date. A future date raises a {@link FutureRegistrationDateException}, which the
921	     * exception handler translates to a 400 Bad Request. A {@code null} date (the default, filled in
922	     * later from the server date) is accepted.
923	     */
924	    private static void rejectFutureRegistrationDate(LocalDate registrationDate) {
925	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
926	            throw new FutureRegistrationDateException(registrationDate);
927	        }
928	    }
929	
930	    /**
931	     * The fixed list of public holidays. An effective registration date that lands on any of these
932	     * is rolled forward, together with weekends, to the next non-holiday business day.
933	     */
934	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
935	        LocalDate.of(2026, 1, 1),
936	        LocalDate.of(2026, 1, 26),
937	        LocalDate.of(2026, 4, 25),
938	        LocalDate.of(2026, 12, 25),
939	        LocalDate.of(2026, 12, 28));
940	
941	    private static LocalDate toBusinessDay(LocalDate date) {
942	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
943	            date = date.plusDays(1);
944	        }
945	        return date;
946	    }
947	
948	    private static boolean isWeekend(LocalDate date) {
949	        return switch (date.getDayOfWeek()) {
950	            case SATURDAY, SUNDAY -> true;
951	            default -> false;
952	        };
953	    }
