955	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
956	    @Override
957	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
958	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
959	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
960	            OwnerDto replay = idempotentCreates.get(idempotencyKey);
961	            if (replay != null) {
962	                return new ResponseEntity<>(replay, HttpStatus.OK);
963	            }
964	        }
965	        String normalizedLine1 = null;
966	        String normalizedLine2 = null;
967	        String composedAddress;
968	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
969	            normalizedLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
970	            if (!isBlank(ownerFieldsDto.getAddressLine2())) {
971	                normalizedLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
972	            }
973	            composedAddress = normalizedLine2 == null
974	                ? normalizedLine1
975	                : normalizedLine1 + " " + normalizedLine2;
976	        } else {
977	            composedAddress = normalizeAddress(ownerFieldsDto.getAddress());
978	        }
979	        rejectMissingOrBlankFields(ownerFieldsDto, composedAddress);
980	        rejectCityAtCapacity(ownerFieldsDto.getCity());
981	        HttpHeaders headers = new HttpHeaders();
982	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
983	        owner.setAddress(composedAddress);
984	        owner.setAddressLine1(normalizedLine1);
985	        owner.setAddressLine2(normalizedLine2);
986	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
987	        owner.setTelephone(normalizedTelephone);
988	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
989	        owner.setEmail(normalizedEmail);
990	        validatePostcode(owner.getCity(), owner.getPostcode());
991	        String householdId = householdIdFor(owner.getLastName(), owner.getPostcode());
992	        rejectDuplicateIdentity(normalizedTelephone, normalizedEmail, owner.getLastName());
993	        rejectFutureRegistrationDate(owner.getRegistrationDate());
994	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
995	        LocalDate registrationDate = toBusinessDay(effectiveDate);
996	        rejectDailyOwnerLimit(registrationDate);
997	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
998	        owner.setCapacityWarning(capacityWarningFor(owner.getCity()));
999	        owner.setRegistrationDate(registrationDate);
1000	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
1001	        owner.setCustomerCode(deduplicateCustomerCode(customerCodeFor(region, normalizedTelephone, owner.getLastName())));
1002	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
1003	        owner.setHouseholdId(householdId);
1004	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
1005	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1006	        int membershipPoints = membershipPointsFor(owner);
1007	        owner.setMembershipPoints(membershipPoints);
1008	        int membershipLevel = membershipLevelForPoints(membershipPoints);
1009	        // A declared household member (sharesHousehold) keeps its point-derived level; an owner
1010	        // admitted into an existing household implicitly has its level capped one above the
1011	        // household's current maximum.
1012	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
1013	            membershipLevel = capMembershipLevelByHousehold(membershipLevel, owner.getHouseholdId());
1014	        }
1015	        owner.setMembershipLevel(membershipLevel);
1016	        Integer possibleDuplicateOf = findPossibleDuplicateOf(ownerFieldsDto, normalizedTelephone, normalizedEmail);
1017	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
1018	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
1019	        this.clinicService.saveOwner(owner);
1020	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
1021	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(), owner.getMembershipNumber());
1022	        emitOwnerCreatedEvent(owner);
1023	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
1024	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
1025	            idempotentCreates.put(idempotencyKey, ownerDto);
1026	        }
1027	        headers.setLocation(UriComponentsBuilder.newInstance()
1028	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
1029	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
1030	    }
1031	
1032	    /**
1033	     * Emits the immutable {@code OWNER_CREATED} structured event to the {@code AUDIT} logger as a
1034	     * JSON object {@code {seq, ownerId, customerCode, membershipLevel, event}}. The {@code seq} is a
1035	     * per-application monotonically increasing integer that totally orders creates, and
1036	     * {@code customerCode} carries the owner's current primary identifier
1037	     * ({@link #primaryIdentifierOf}) - the {@code customerCode} today, and whatever supersedes it
1038	     * later. This is a distinct line from the human-readable audit line.
1039	     */
1040	    private void emitOwnerCreatedEvent(Owner owner) {
1041	        Map<String, Object> event = new LinkedHashMap<>();
1042	        event.put("seq", OWNER_EVENT_SEQ.incrementAndGet());
1043	        event.put("ownerId", owner.getId());
1044	        event.put("customerCode", primaryIdentifierOf(owner));
1045	        event.put("membershipLevel", owner.getMembershipLevel());
1046	        event.put("event", "OWNER_CREATED");
1047	        AUDIT.info(EVENT_MAPPER.writeValueAsString(event));
1048	    }
1049	
1050	    /**
1051	     * The owner's current primary identifier carried by the {@code OWNER_CREATED} event: the
1052	     * {@code customerCode} today. When the {@code customerCode} is later unified into the
1053	     * {@code memberId}, that becomes the primary identifier and this is the single place to switch,
1054	     * so the event follows automatically.
1055	     */
1056	    private static String primaryIdentifierOf(Owner owner) {
1057	        return owner.getCustomerCode();
1058	    }
