57	    /**
58	     * Derive the owner's locality (region) from its region-and-hash {@code customerCode}: the
59	     * {@code REGION} portion is the segment before the first {@code '-'} (e.g. {@code "NSW-1A2B3C4D"}
60	     * yields {@code "NSW"}). This shares the identity's region derivation, where the postcode range
61	     * takes precedence (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and the city-to-region table is
62	     * the fallback. For an owner without a {@code customerCode} the same region is recomputed directly
63	     * from the postcode then city, otherwise "UNKNOWN".
64	     */
65	    default String deriveLocality(Owner owner) {
66	        if (owner == null) {
67	            return null;
68	        }
69	        String customerCode = owner.getCustomerCode();
70	        if (customerCode != null) {
71	            int dash = customerCode.indexOf('-');
72	            if (dash > 0) {
