91	                // not a numeric postcode; fall back to the city-to-region table
92	            }
93	        }
94	        String city = owner.getCity();
95	        if ("Sydney".equals(city)) {
96	            return "NSW";
97	        }
98	        if ("Melbourne".equals(city)) {
99	            return "VIC";
100	        }
101	        if ("Brisbane".equals(city)) {
102	            return "QLD";
103	        }
104	        return "UNKNOWN";
105	    }
106	
107	    /**
108	     * Derive the owner's marketing segment, formatted {@code '<TIER>_<AREA>'}. TIER is
109	     * {@code "PREMIUM"} when the owner's {@code membershipLevel} is 3 or more, otherwise
110	     * {@code "STANDARD"} (a missing membershipLevel counts as below 3). AREA is {@code "METRO"}
111	     * when the owner's locality is a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}.
112	     * Returns null when the owner is absent.
113	     */
114	    default String deriveOwnerSegment(Owner owner) {
115	        if (owner == null) {
116	            return null;
117	        }
118	        Integer membershipLevel = owner.getMembershipLevel();
119	        String tier = (membershipLevel != null && membershipLevel >= 3) ? "PREMIUM" : "STANDARD";
120	        String locality = deriveLocality(owner);
121	        boolean metro = "NSW".equals(locality) || "VIC".equals(locality) || "QLD".equals(locality);
122	        return tier + "_" + (metro ? "METRO" : "REGIONAL");
123	    }
124	
125	    /**
126	     * Derive the owner's IANA timezone from its locality/region using the fixed region-to-timezone
127	     * table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). The region is
128	     * the same value reported as {@code locality}. Returns null when the owner is absent or the region
129	     * has no known timezone.
130	     */
131	    default String deriveTimezone(Owner owner) {
132	        if (owner == null) {
133	            return null;
134	        }
135	        String region = deriveLocality(owner);
136	        if ("NSW".equals(region)) {
137	            return "Australia/Sydney";
138	        }
139	        if ("VIC".equals(region)) {
140	            return "Australia/Melbourne";
141	        }
142	        if ("QLD".equals(region)) {
143	            return "Australia/Brisbane";
144	        }
145	        return null;
146	    }
147	
148	    /**
149	     * Derive the owner's check digit: a single Luhn check digit (0-9) computed over the
150	     * digits contained in the owner's customerCode. Non-digit characters are ignored.
151	     * Returns null when the owner or its customerCode is absent.
152	     */
153	    default Integer deriveCheckDigit(Owner owner) {
154	        if (owner == null || owner.getCustomerCode() == null) {
155	            return null;
156	        }
157	        String code = owner.getCustomerCode();
158	        int sum = 0;
159	        boolean dbl = true;
160	        for (int i = code.length() - 1; i >= 0; i--) {
161	            char c = code.charAt(i);
162	            if (c < '0' || c > '9') {
163	                continue;
164	            }
165	            int d = c - '0';
166	            if (dbl) {
167	                d *= 2;
168	                if (d > 9) {
169	                    d -= 9;
170	                }
171	            }
172	            sum += d;
173	            dbl = !dbl;
174	        }
175	        return (10 - (sum % 10)) % 10;
176	    }
