186	        if (owner == null || owner.getBirthDate() == null) {
187	            return null;
188	        }
189	        java.time.LocalDate reference = owner.getRegistrationDate() != null
190	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
191	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
192	        if (age < 18) {
193	            return "MINOR";
194	        }
195	        if (age < 65) {
196	            return "ADULT";
197	        }
198	        return "SENIOR";
199	    }
200	
201	    /**
202	     * Known E.164 country calling codes, longest first, used to split a stored telephone into its
203	     * country code and national digits. A number whose code is not listed falls back to a two-digit
204	     * country code, the most common E.164 length.
205	     */
206	    String[] KNOWN_CALLING_CODES = { "61", "1" };
207	
208	    /**
209	     * Format the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
210	     * the national digits grouped in threes (e.g. {@code "+61412345678"} becomes
211	     * {@code "+61 412 345 678"}). Returns null when the owner or its telephone is absent, and returns
212	     * the value unchanged when it is not in E.164 form.
213	     */
214	    default String deriveTelephoneDisplay(Owner owner) {
215	        if (owner == null || owner.getTelephone() == null) {
216	            return null;
217	        }
218	        String telephone = owner.getTelephone();
219	        if (!telephone.startsWith("+")) {
220	            return telephone;
221	        }
222	        String digits = telephone.substring(1);
223	        int codeLength = 2;
224	        for (String code : KNOWN_CALLING_CODES) {
225	            if (digits.startsWith(code) && digits.length() > code.length()) {
226	                codeLength = code.length();
227	                break;
228	            }
229	        }
230	        if (digits.length() <= codeLength) {
231	            return telephone;
232	        }
233	        String national = digits.substring(codeLength);
234	        StringBuilder display = new StringBuilder("+").append(digits, 0, codeLength);
235	        for (int i = 0; i < national.length(); i += 3) {
236	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
237	        }
238	        return display.toString();
239	    }
240	
241	    /**
242	     * Derive the owner's salutation: the honorific {@code title} followed by a single space and the
243	     * {@code lastName} (e.g. {@code "DR Who"}). When the owner has no title (null or blank) the
244	     * salutation is just the {@code lastName}. Returns null when the owner is absent.
245	     */
246	    default String deriveSalutation(Owner owner) {
247	        if (owner == null) {
248	            return null;
249	        }
250	        String title = owner.getTitle();
251	        String lastName = owner.getLastName();
252	        if (title == null || title.isBlank()) {
253	            return lastName;
254	        }
255	        return title + " " + lastName;
256	    }
257	
258	    /**
259	     * Derive the owner's fiscal year from its business-day-adjusted {@code registrationDate},
260	     * formatted {@code 'FY<YY>'} where YY is the last two digits of the fiscal year. The fiscal
261	     * year starts on 1 July and is labelled by the calendar year in which it ends, so a
262	     * registrationDate on or after 1 July belongs to the fiscal year ending the following calendar
263	     * year. Returns null when the owner or its registrationDate is absent.
264	     */
265	    default String deriveFiscalYear(Owner owner) {
266	        if (owner == null || owner.getRegistrationDate() == null) {
267	            return null;
268	        }
269	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
270	        int fiscalYear = registrationDate.getMonthValue() >= java.time.Month.JULY.getValue()
271	            ? registrationDate.getYear() + 1 : registrationDate.getYear();
272	        return String.format("FY%02d", fiscalYear % 100);
273	    }
274	
275	    /**
276	     * Derive the owner's {@code identityKey}: the 64-character lower-case SHA-256 hex digest over
277	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The telephone and
278	     * email are the owner's already-normalized stored values (E.164 telephone, lower-cased email); a
279	     * null email contributes an empty middle segment. Returns null when the owner is absent. This is
280	     * the same key duplicate detection compares on create.
281	     */
282	    default String deriveIdentityKey(Owner owner) {
283	        if (owner == null) {
284	            return null;
285	        }
286	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
287	        String email = owner.getEmail() == null ? "" : owner.getEmail();
288	        return sha256Hex(telephone + "|" + email + "|" + soundex(owner.getLastName()));
289	    }
290	
291	    /**
292	     * The American Soundex code of a name: its first letter followed by up to three digits encoding
293	     * the remaining consonants (b/f/p/v->1, c/g/j/k/q/s/x/z->2, d/t->3, l->4, m/n->5, r->6), with
294	     * adjacent duplicate codes collapsed, vowels (and y) resetting the run, and h/w transparent. The
295	     * result is padded with zeros to exactly four characters. A null or letterless name yields "".
296	     */
297	    private static String soundex(String name) {
298	        if (name == null) {
299	            return "";
300	        }
301	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
302	        if (letters.isEmpty()) {
303	            return "";
304	        }
305	        StringBuilder code = new StringBuilder();
306	        code.append(letters.charAt(0));
307	        char prev = soundexCode(letters.charAt(0));
308	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
309	            char c = letters.charAt(i);
310	            if (c == 'H' || c == 'W') {
311	                continue;
312	            }
313	            char digit = soundexCode(c);
314	            if (digit != '0' && digit != prev) {
315	                code.append(digit);
316	            }
317	            prev = digit;
318	        }
319	        while (code.length() < 4) {
320	            code.append('0');
321	        }
322	        return code.toString();
323	    }
324	
325	    /**
326	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a vowel, y, h or w.
327	     */
328	    private static char soundexCode(char c) {
329	        return switch (c) {
330	            case 'B', 'F', 'P', 'V' -> '1';
331	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
332	            case 'D', 'T' -> '3';
333	            case 'L' -> '4';
334	            case 'M', 'N' -> '5';
335	            case 'R' -> '6';
336	            default -> '0';
337	        };
338	    }
339	
340	    /**
341	     * The full lower-case SHA-256 hex digest (64 characters) of the UTF-8 bytes of {@code value}.
342	     */
343	    private static String sha256Hex(String value) {
344	        try {
345	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
346	            StringBuilder sb = new StringBuilder(digest.length * 2);
347	            for (byte b : digest) {
348	                sb.append(String.format("%02x", b));
349	            }
350	            return sb.toString();
351	        }
352	        catch (NoSuchAlgorithmException ex) {
353	            throw new IllegalStateException("SHA-256 not available", ex);
354	        }
355	    }
356	
357	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
358	        OwnerPageDto ownerPageDto = new OwnerPageDto();
359	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
360	        ownerPageDto.setPage(ownerPage.getNumber());
361	        ownerPageDto.setSize(ownerPage.getSize());
362	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
363	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
364	        return ownerPageDto;
365	    }
